 For example, if the input string is "hello", the output should be "h1llo".

# Solution
vowels = ["a", "e", "i", "o", "u"]
def replace_vowels(s):
    return "".join([chr(ord(c) + 1) for c in s if c not in vowels])
print(replace_vowels("hello"))

